def generate_social_network(n_nodes=100, n_communities=4, intra_prob=0.3, inter_prob=0.05):
    """
    Generate a synthetic social network with community structure
    """
    nodes_per_community = n_nodes // n_communities
    G = nx.Graph()

    community_map = {}
    node_id = 0

    for comm_id in range(n_communities):
        for i in range(nodes_per_community):
            G.add_node(node_id)
            community_map[node_id] = comm_id
            node_id += 1

    for u in G.nodes():
        for v in G.nodes():
            if u < v:
                if community_map[u] == community_map[v]:
                    if np.random.random() < intra_prob:
                        G.add_edge(u, v, weight=1.0)
                else:
                    if np.random.random() < inter_prob:
                        G.add_edge(u, v, weight=0.5)

    return G, community_map

