def collaborative_filtering_recommend(target_user, similarity_df, rating_matrix, top_n=5):
    similar_users = find_similar_users(target_user, similarity_df, top_n=10)

    user_rated = set(rating_matrix.loc[target_user][rating_matrix.loc[target_user] > 0].index)
    recommendations = {}

    for sim_user, sim_score in similar_users.items():
        for item in rating_matrix.columns:
            if item not in user_rated and rating_matrix.loc[sim_user, item] > 0:
                if item not in recommendations:
                    recommendations[item] = 0
                recommendations[item] += rating_matrix.loc[sim_user, item] * sim_score

    return sorted(recommendations.items(), key=lambda x: x[1], reverse=True)[:top_n]

