    similar_users = user_similarity_df[user_id].sort_values(ascending=False)[1:]

    # Get items rated by similar users but not by target user
    user_rated = set(user_item_matrix.loc[user_id][user_item_matrix.loc[user_id] > 0].index)

    recommendations = {}
    for sim_user, similarity in similar_users.items():
        sim_user_items = user_item_matrix.loc[sim_user][user_item_matrix.loc[sim_user] > 0]
        for item, rating in sim_user_items.items():
            if item not in user_rated:
                if item not in recommendations:
                    recommendations[item] = 0
                recommendations[item] += similarity * rating

    # Return top N recommendations
    top_recs = sorted(recommendations.items(), key=lambda x: x[1], reverse=True)[:n_recommendations]
    return top_recs

# Get recommendations for user 1
recs = get_recommendations(1, user_item_matrix, user_similarity_df, n_recommendations=2)
print(f"Recommendations for user 1: {recs}")

# Get top-k recommendations for users
def get_topk_recommendations(scores, k=10):
    recommendations = {}
    for user_idx in range(scores.shape[0]):
        top_items = np.argsort(scores[user_idx])[-k:][::-1]
        recommendations[user_idx] = top_items
    return recommendations

